// === Tab: mySketch ===
/***

A recursive neural structure that grows like a synthetic brain, sending glowing signals through branching pathways.
Each branch recursively divides into smaller cognitive networks while pulses travel through the system like thoughts propagating across artificial synapses.

Built with recursion, oscillation, and signal propagation to explore the visual language of machine intelligence, neural geometry, and computational cognition.

Click to inject additional signal pulses into the network.
***/

let root;
let pulses = [];
let t = 0;
let yStart = 0.80;
function setup() {
  createCanvas(windowWidth, windowHeight);
  angleMode(RADIANS);
  strokeCap(ROUND);

  root = new SignalBranch(width * 0.5, height * yStart, 160, -PI / 2, 0);
}

function draw() {
  background(8, 10, 16, 35);

  t += 0.01;

  drawGlowField();

  root.update();
  root.display();

  if (frameCount % 35 === 0) {
    pulses.push(new Pulse(root));
  }

  for (let i = pulses.length - 1; i >= 0; i--) {
    pulses[i].update();
    pulses[i].display();

    if (pulses[i].finished) {
      pulses.splice(i, 1);
    }
  }

  drawCore();
}

class SignalBranch {
  constructor(x, y, len, angle, depth) {
    this.x = x;
    this.y = y;
    this.len = len;
    this.angle = angle;
    this.depth = depth;
    this.children = [];

    this.phase = random(TWO_PI);
    this.growth = 0;

    this.endX = this.x + cos(this.angle) * this.len;
    this.endY = this.y + sin(this.angle) * this.len;

    if (depth < 8 && len > 8) {
      let childCount = depth < 2 ? 3 : 2;

      for (let i = 0; i < childCount; i++) {
        let spread = map(depth, 0, 8, 0.85, 0.25);
        let offset = map(i, 0, childCount - 1, -spread, spread);
        let newAngle = angle + offset + random(-0.15, 0.15);
        let newLen = len * random(0.62, 0.76);

        this.children.push(
          new SignalBranch(this.endX, this.endY, newLen, newAngle, depth + 1)
        );
      }
    }
  }

  update() {
    this.growth = min(this.growth + 0.015, 1);

    let sway = sin(t * 2 + this.phase) * 0.035;
    this.endX = this.x + cos(this.angle + sway) * this.len * this.growth;
    this.endY = this.y + sin(this.angle + sway) * this.len * this.growth;

    for (let child of this.children) {
      child.x = this.endX;
      child.y = this.endY;
      child.update();
    }
  }

  display() {
    let alpha = map(this.depth, 0, 8, 190, 35);
    let weight = map(this.depth, 0, 8, 4.5, 0.8);

    // outer glow
    stroke(70, 170, 255, alpha * 0.18);
    strokeWeight(weight * 4);
    line(this.x, this.y, this.endX, this.endY);

    // main neural line
    stroke(120, 220, 255, alpha);
    strokeWeight(weight);
    line(this.x, this.y, this.endX, this.endY);

    // tiny synapse node
    noStroke();
    fill(140, 230, 255, alpha);
    circle(this.endX, this.endY, weight * 2.2);

    for (let child of this.children) {
      child.display();
    }
  }
}

class Pulse {
  constructor(branch) {
    this.path = [];
    this.collectPath(branch);
    this.index = 0;
    this.progress = 0;
    this.finished = false;
    this.size = random(5, 9);
  }

  collectPath(branch) {
    this.path.push(branch);

    if (branch.children.length > 0) {
      let next = random(branch.children);
      this.collectPath(next);
    }
  }

  update() {
    this.progress += 0.045;

    if (this.progress >= 1) {
      this.progress = 0;
      this.index++;

      if (this.index >= this.path.length) {
        this.finished = true;
      }
    }
  }

  display() {
    if (this.finished) return;

    let b = this.path[this.index];

    let x = lerp(b.x, b.endX, this.progress);
    let y = lerp(b.y, b.endY, this.progress);

    noStroke();

    fill(70, 180, 255, 45);
    circle(x, y, this.size * 5);

    fill(120, 240, 255, 150);
    circle(x, y, this.size * 2.2);

    fill(255);
    circle(x, y, this.size * 0.65);
  }
}

function drawCore() {
  let pulse = 1 + sin(frameCount * 0.05) * 0.15;

  noStroke();
  fill(80, 180, 255, 35);
  circle(width * 0.5, height * yStart, 90 * pulse);

  fill(120, 230, 255, 120);
  circle(width * 0.5, height * yStart, 32 * pulse);

  fill(255);
  circle(width * 0.5, height * yStart, 8 * pulse);
}

function drawGlowField() {
  noStroke();

  for (let i = 0; i < 35; i++) {
    var x = noise(i * 0.2, t) * width;
    var y = noise(i * 0.25, t + 20) * height;
    let s = noise(i, t) * 4 + 1;

    fill(80, 160, 255, 18);
    circle(x, y, s);
  }
}

function mousePressed() {
  pulses.push(new Pulse(root));
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  root = new SignalBranch(width * 0.5, height * yStart, 160, -PI / 2, 0);
  pulses = [];
}

